import {STAGES,FIELDWORK_FIELDS,makeSourceCode,buildTaskQueue,groupYield,responseSummary} from './fieldwork.js';
import {AGE_BANDS,normalizeSampling,validateSampling,samplingSummary} from './sampling.js';
import {normalizeText,formatNumber} from './core.js';
import {userToday,watchFormDraft,restoreFormDraft,clearFormDraft,captureFormDraft,readDraft,writeDraft,clearDraft,showFormErrors,checkFormValidity} from './usability.js';
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=id=>`<svg aria-hidden="true"><use href="#i-${id}"/></svg>`;
const today=userToday;
const dateLabel=value=>value?new Date(`${value}T00:00:00`).toLocaleDateString('vi-VN'):'Chưa hẹn';
const rateLabel=value=>value===null?'Chưa rõ':`${new Intl.NumberFormat('vi-VN',{maximumFractionDigits:1}).format(value*100)}%`;
const stageBadge=stage=>`<span class="stage-badge stage-${stage}">${esc(STAGES[stage]||STAGES.new)}</span>`;

export function createFieldworkWorkspace(api){
 let allTasks=false,composerGroup=null,composerMode='invite',workflowTab='progress';
 const groups=()=>api.getState().groups;
 const getGroup=id=>groups().find(g=>g.id===id);
 const elOptions=Object.entries(STAGES).map(([value,label])=>`<option value="${value}">${label}</option>`).join('');
 $('workflow-stage').innerHTML=elOptions;$('stage-filter').insertAdjacentHTML('beforeend',elOptions);
 $('age-inputs').innerHTML=AGE_BANDS.map(({id,label})=>`<label class="field">${label} tuổi<input type="number" min="0" step="1" name="age-${id}" required></label>`).join('');
 function render(){
  const {groups:rows,campaign,sampling,lastExportAt}=api.getState(),summary=responseSummary(rows,campaign.baseline),tasks=buildTaskQueue(rows,{today:today()});
  const empty=rows.length===0,hasSamples=summary.valid>0||summary.receivedKnown>0;$('quick-start').hidden=!empty&&!!campaign.formUrl;$('start-setup').classList.toggle('completed',!!campaign.formUrl);$('start-setup').textContent=campaign.formUrl?'✓ Link khảo sát đã lưu':'1. Thêm link khảo sát';$('start-add').classList.toggle('completed',!empty);$('start-counts').disabled=empty;document.querySelector('.fieldwork-heading').hidden=empty;document.querySelector('.field-top-grid').hidden=empty&&!hasSamples;document.querySelector('.pipeline-panel').hidden=empty;$('field-analytics').hidden=empty&&!hasSamples;$('backup-reminder').hidden=empty&&!hasSamples;document.querySelector('#fieldwork-panel > .bottom-callout').hidden=empty;
  $('nav-due').textContent=tasks.length;$('task-count').textContent=tasks.length;$('today-label').textContent=new Date().toLocaleDateString('vi-VN',{day:'numeric',month:'long',timeZone:'Asia/Bangkok'});
  const backupText=lastExportAt?`Lần xuất bản sao gần nhất: ${new Date(lastExportAt).toLocaleString('vi-VN',{timeZone:'Asia/Bangkok'})}`:'Bạn chưa xuất bản sao. Dữ liệu hiện chỉ nằm trong trình duyệt này.';
  $('backup-status').textContent=backupText;$('plan-backup-status').textContent=backupText;
  $('backup-reminder').classList.toggle('overdue',!lastExportAt||Date.now()-Date.parse(lastExportAt)>7*86400000);
  const shown=allTasks?tasks:tasks.slice(0,5);
  $('task-list').innerHTML=shown.length?shown.map(t=>{const g=getGroup(t.groupId),overdue=t.dueAt&&t.dueAt<today();return `<div class="task-row"><span class="task-indicator ${t.type==='blocked'?'blocked':overdue?'overdue':''}">${icon(t.type==='blocked'?'shield':t.type==='verify'?'info':'clock')}</span><div><strong>${esc(t.title)}</strong><span>${esc(g.name)} · ${t.dueAt?`${overdue?'Quá hạn · ':''}${dateLabel(t.dueAt)}`:'Cần xử lý'}</span></div><button class="task-action" data-task="${esc(g.id)}" data-type="${t.type}">${t.type==='verify'?'Xác minh':'Cập nhật'}${icon('arrow')}</button></div>`;}).join('')+(tasks.length>5?`<button class="text-link show-tasks" id="show-all-tasks">${allTasks?'Thu gọn':`Xem thêm ${tasks.length-5} việc`}</button>`:''):`<div class="task-empty">${icon('check')}<div><strong>${rows.length?'Chưa có việc đến hạn':'Bắt đầu bằng một nhóm thật'}</strong><p>${rows.length?'Lịch sắp tới vẫn hiển thị ở từng nhóm bên dưới.':'Thêm nhóm đã xác minh để lập lịch và theo dõi xin phép.'}</p></div></div>`;
  $('show-all-tasks')?.addEventListener('click',()=>{allTasks=!allTasks;render();});
  $('quality-summary').innerHTML=`<div class="quality-cells"><div><strong>${formatNumber(summary.receivedKnown)}</strong><span>Đã nhận, biết nguồn</span></div><div class="valid"><strong>${formatNumber(summary.valid)}</strong><span>Hợp lệ / 500</span></div><div class="pending"><strong>${formatNumber(summary.pending)}</strong><span>Chưa rà soát đã biết</span></div><div><strong>${formatNumber(summary.rejected)}</strong><span>Đã loại</span></div></div><div class="quality-line"><span>Tỷ lệ hợp lệ toàn bộ</span><strong>${rateLabel(summary.rate)}</strong></div><p class="small-note">${summary.unknownSources||summary.baselineUnknown?`${summary.unknownSources?`${summary.unknownSources} nhóm chưa nhập tổng đã nhận. `:''}${summary.baselineUnknown?`${formatNumber(campaign.baseline)} mẫu hợp lệ từ nguồn khác đã tính trong tổng; chưa có tổng đã nhận. `:''}Tổng đã nhận và chưa rà soát chỉ gồm các nguồn đã biết.`:'Các số liệu do bạn nhập sau khi kiểm tra; không được Google Form đồng bộ.'}</p>`;
  const selected=$('stage-filter').value;
  $('pipeline-stages').innerHTML=Object.entries(STAGES).map(([stage,label])=>`<button class="pipeline-stage ${selected===stage?'active':''}" data-stage="${stage}" aria-pressed="${selected===stage}"><span>${label}</span><strong>${rows.filter(g=>(g.stage||'new')===stage).length}</strong><i></i></button>`).join('');
  const query=normalizeText($('field-search').value),filtered=rows.filter(g=>(!selected||g.stage===selected)&&normalizeText(`${g.name} ${g.sourceCode}`).includes(query));
  $('workflow-rows').innerHTML=filtered.map(g=>`<tr><td><button class="table-group-name" data-basic="${esc(g.id)}">${esc(g.name)}</button><span class="source-code">${esc(g.sourceCode||makeSourceCode(g.id))} · ${esc(g.location)}</span></td><td>${stageBadge(g.stage||'new')}${g.postedAt?`<small>Đăng ${dateLabel(g.postedAt)}</small>`:''}</td><td data-label="Việc tiếp theo"><span class="next-date ${g.nextActionAt&&g.nextActionAt<today()?'late':''}">${dateLabel(g.nextActionAt)}</span><small>${esc(g.nextAction||(['paused','rejected'].includes(g.stage)?g.stopReason||'Không nhắc lại':'Chưa ghi việc tiếp theo'))}</small></td><td data-label="Mẫu hợp lệ"><strong class="valid-count">${formatNumber(g.responses)}</strong>${g.received!==null?`<small>/ ${formatNumber(g.received)} đã nhận</small>`:'<small>Chưa rõ tổng nhận</small>'}</td><td class="workflow-actions"><div class="row-actions"><button class="button primary compact" data-counts="${esc(g.id)}">Cập nhật mẫu</button><button class="button secondary compact" data-workflow="${esc(g.id)}">Tiến độ</button><button class="icon-button" data-compose="${esc(g.id)}" aria-label="Soạn nội dung cho ${esc(g.name)}" title="Soạn lời mời / xin phép">${icon('edit')}</button></div></td></tr>`).join('');
  $('field-empty').hidden=rows.length>0;$('workflow-rows').closest('.table-wrap').hidden=!rows.length;
  if(rows.length&&!filtered.length)$('workflow-rows').innerHTML='<tr><td colspan="5" class="no-results">Không có nhóm khớp bộ lọc. Chọn Tất cả hoặc đổi từ khóa.</td></tr>';
  renderSampling(sampling,summary.valid);
  const ranked=rows.filter(g=>g.responses>0||g.received!==null&&g.received>0).sort((a,b)=>b.responses-a.responses).slice(0,6);
  $('yield-summary').innerHTML=ranked.length?`<div class="table-wrap"><table class="yield-table"><thead><tr><th>Nguồn</th><th>Hợp lệ</th><th>Tỷ lệ hợp lệ</th><th>Phút / mẫu</th></tr></thead><tbody>${ranked.map(g=>{const stats=groupYield(g);return `<tr><td><button data-workflow="${esc(g.id)}">${esc(g.name)}</button><small>${esc(g.sourceCode)}</small></td><td>${formatNumber(stats.valid)}</td><td>${rateLabel(stats.rate)}</td><td>${stats.minutesPerValid===null?'Chưa ghi':formatNumber(stats.minutesPerValid)}</td></tr>`;}).join('')}</tbody></table></div><p class="small-note">Tỷ lệ = hợp lệ / tổng đã nhận. Phút/mẫu chỉ tính khi bạn đã nhập công sức. Các nhóm đã dừng vẫn giữ số mẫu.</p>`:'<div class="insight-empty">Chưa có phản hồi được ghi nhận.<p>Cập nhật tổng đã nhận, mẫu hợp lệ và thời gian ở “Theo dõi” để so sánh nguồn.</p></div>';
 }
 function renderSampling(input,total){const summary=samplingSummary(input,total),sampling=normalizeSampling(input);$('sampling-summary').innerHTML=`${summary.warnings.filter(text=>text.includes('vượt')||text.includes('chỉ tiêu là 0')||text.includes('chưa hợp lệ')).map(text=>`<div class="distribution-warning">${icon('info')}${esc(text)}</div>`).join('')}<div class="city-progress">${summary.cities.map(city=>`<div class="city-line"><div><strong>${city.label}</strong><span>${formatNumber(city.actual)} / ${formatNumber(city.target)} <em>còn ${formatNumber(city.remaining)}</em></span></div><div class="bar-track"><i style="width:${Math.min(100,city.percent)}%"></i></div></div>`).join('')}</div><p class="small-note">Chưa phân loại thành phố: <strong>${formatNumber(summary.cityUnknown)}</strong> mẫu. Chỉ tiêu 250/250 là mốc điều phối có thể sửa.</p><div class="age-distribution">${summary.ageRows.map(age=>`<div><span>${age.label}</span><div class="bar-track"><i style="width:${Math.min(100,age.percent)}%"></i></div><strong>${formatNumber(age.actual)}</strong></div>`).join('')}</div><p class="small-note">Chưa phân loại độ tuổi: <strong>${formatNumber(summary.ageUnknown)}</strong> mẫu. Phân bổ không làm tăng tổng phản hồi.</p>${sampling.deadline?`<div class="deadline-note">${icon('clock')}Dự kiến kết thúc: ${dateLabel(sampling.deadline)}${sampling.deadline<today()&&total<500?' · Đã qua ngày dự kiến':''}</div>`:''}`;}
 function activateWorkflowTab(next){if(!next)return;workflowTab=next;document.querySelectorAll('[data-workflow-tab]').forEach(el=>{const active=el.dataset.workflowTab===next;el.classList.toggle('active',active);el.setAttribute('aria-selected',String(active));});document.querySelectorAll('[data-workflow-panel]').forEach(el=>el.hidden=el.dataset.workflowPanel!==next);}
 function updateStageFields(fill=false){const form=$('workflow-form'),stage=form.elements.stage.value;document.querySelectorAll('[data-stage-date]').forEach(label=>label.hidden=label.dataset.stageDate!==stage);const dateName={contacted:'contactedAt',pending:'submittedAt',posted:'postedAt'}[stage];if(fill&&dateName&&!form.elements.namedItem(dateName).value)form.elements.namedItem(dateName).value=today();form.elements.postUrl.closest('label').hidden=!['pending','posted'].includes(stage)&&!form.elements.postUrl.value;}
 function openWorkflow(id,tab='progress'){const g=getGroup(id);if(!g)return;const form=$('workflow-form');form.reset();form.querySelectorAll('details').forEach(el=>el.open=false);form.querySelectorAll('[data-inline-error]').forEach(el=>el.remove());form.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));form.elements.id.value=g.id;for(const field of [...FIELDWORK_FIELDS,'responses']){const el=form.elements.namedItem(field);if(el)el.value=g[field]??(field==='stage'?'new':field==='sourceCode'?makeSourceCode(g.id):'');}restoreFormDraft(form,`workflow:${g.id}`);updateStageFields();activateWorkflowTab(tab);$('workflow-title').textContent=g.name;$('workflow-context').textContent=`${g.location||'Chưa rõ khu vực'} · Quyền khảo sát: ${{yes:'đã kiểm tra có',no:'không cho phép',unknown:'chưa xác minh'}[g.surveys]}.`;$('workflow-links').innerHTML=`<a class="button secondary compact" href="${esc(g.url)}" target="_blank" rel="noopener noreferrer">${icon('external')}Mở nhóm</a>${g.postUrl?`<a class="button secondary compact" href="${esc(g.postUrl)}" target="_blank" rel="noopener noreferrer">${icon('external')}Mở bài đã đăng</a>`:''}${g.surveyUrl?`<a class="button secondary compact" href="${esc(g.surveyUrl)}" target="_blank" rel="noopener noreferrer">${icon('external')}Thử link nguồn</a>`:''}`;$('workflow-errors').textContent='';qualityPreview();$('workflow-dialog').showModal();}
 function qualityPreview(){const form=$('workflow-form'),received=form.elements.received.value,valid=+form.elements.responses.value||0,rejected=+form.elements.rejected.value||0;$('quality-preview').textContent=received===''?'Chưa biết tổng đã nhận: chưa tính được số chưa rà soát và tỷ lệ hợp lệ.':+received<valid+rejected?'Số chưa khớp: tổng đã nhận phải ≥ hợp lệ + đã loại.':`${formatNumber(+received-valid-rejected)} phản hồi chưa rà soát · ${rateLabel(+received>0?valid/+received:null)} hợp lệ`;$('quality-preview').classList.toggle('invalid',received!==''&&+received<valid+rejected);}
 function sourceHelp(){api.showInfo('Theo dõi người trả lời đến từ nhóm nào',`<h3>1. Thêm câu hỏi nguồn vào Google Form</h3><p>Tạo một câu hỏi trả lời ngắn, ví dụ “Bạn biết khảo sát từ nguồn nào?”. Dùng mã riêng của mỗi nhóm, không dùng tên hay thông tin cá nhân người trả lời.</p><h3>2. Tạo đường liên kết điền sẵn</h3><p>Trong trình chỉnh sửa Google Form, chọn menu ba chấm → “Nhận đường liên kết điền sẵn” (Get pre-filled link). Điền mã nguồn vào câu hỏi vừa tạo, giữ trống các câu hỏi khác rồi lấy link.</p><h3>3. Dán vào hồ sơ nhóm</h3><p>Mở “Theo dõi”, dán link vào “Link Google Form đã điền sẵn mã nguồn”. Mở link thử và kiểm tra đúng mã trước khi chia sẻ. Bài mời riêng cho nhóm sẽ dùng link này.</p><h3>4. Rà soát và ghi tổng lũy kế</h3><p>Lọc theo câu trả lời nguồn trong Google Sheets, rà soát điều kiện và loại trùng, rồi nhập tổng đã nhận / hợp lệ / loại vào app. Người trả lời có thể sửa câu trả lời nguồn; đây là nguồn tự báo cáo, không phải theo dõi lượt nhấp tự động.</p><div class="mini-note">App không tự thêm câu hỏi vào Google Form, không gắn mã UTM để hứa đo phản hồi và không tự tải dữ liệu trả lời.</div>`);}
 function openComposer(id,type='invite'){composerGroup=getGroup(id);if(!composerGroup)return;composerMode=type;fillComposer();$('composer-dialog').showModal();}
 function fillComposer(){const g=composerGroup,{campaign}=api.getState(),link=g.surveyUrl||campaign.formUrl||'[Dán link Google Form]',blocked=g.surveys==='no'||['paused','rejected'].includes(g.stage);$('composer-title').textContent=g.name;$('compose-invite').classList.toggle('active',composerMode==='invite');$('compose-admin').classList.toggle('active',composerMode==='admin');const missingLink=!(g.surveyUrl||campaign.formUrl);$('composer-setup').hidden=!missingLink;$('copy-composer').disabled=composerMode==='invite'&&(blocked||missingLink);$('composer-preview').hidden=!(g.surveyUrl||campaign.formUrl);$('composer-preview').href=g.surveyUrl||campaign.formUrl||'#';
  $('composer-note').textContent=composerMode==='invite'&&missingLink?'Chưa có link khảo sát. Thêm link trước khi sao chép bài mời.':composerMode==='admin'?'Mẫu xin phép riêng. Hãy điền đúng tên / đơn vị nghiên cứu trước khi gửi.':blocked?'Nhóm đang dừng, bị từ chối hoặc không cho khảo sát. Hãy kiểm tra lại tình trạng trước khi dùng bài mời.':g.surveyUrl?`Đang dùng link điền sẵn do bạn nhập. Mã nguồn trong hồ sơ: ${g.sourceCode}; hãy mở thử để kiểm tra câu trả lời nguồn khớp mã.`:`Chưa có link điền sẵn mã ${g.sourceCode}; đang dùng link chung. Chưa thể đối chiếu nguồn nếu câu hỏi nguồn chưa được thiết lập.`;
  $('composer-source-code').value=g.sourceCode||makeSourceCode(g.id);$('composer-text').value=composerMode==='admin'?`Chào anh/chị quản trị nhóm “${g.name}”,\n\nMình là [Tên người thực hiện / đơn vị], đang thực hiện khảo sát về “${campaign.topic}”. Mình muốn xin phép chia sẻ một bài mời khảo sát trong nhóm.\n\nĐối tượng là người 18–65 tuổi, đang sinh sống tại TP.HCM hoặc Hà Nội và có ý định mua nhà. Bảng hỏi dự kiến khoảng ${campaign.minutes} phút, tham gia tự nguyện; mục đích và cách dùng dữ liệu được trình bày ở đầu biểu mẫu.\n\nAnh/chị có cho phép chia sẻ Google Form không, và nếu được thì cần tuân thủ điều kiện nào? Mình cũng mong được biết nhóm có cho đăng ẩn danh đối với bài khảo sát không.\n\nLink để anh/chị xem trước: ${link}\n\nCảm ơn anh/chị. Mình sẽ tuân thủ nội quy và tôn trọng quyết định của quản trị viên.`:`Chào mọi người trong nhóm “${g.name}”,\n\nMình đang thực hiện khảo sát về “${campaign.topic}” và mong nhận được chia sẻ từ các bạn 18–65 tuổi, đang sống tại TP.HCM hoặc Hà Nội, có ý định mua nhà.\n\nBảng hỏi dự kiến mất khoảng ${campaign.minutes} phút. Việc tham gia hoàn toàn tự nguyện; bạn vui lòng đọc phần giới thiệu về mục đích và cách sử dụng dữ liệu trước khi trả lời.\n\nLink khảo sát: ${link}\n\nCảm ơn mọi người đã dành thời gian. Mình sẽ tuân thủ nội quy của nhóm.`;
  const saved=readDraft(`composer:${g.id}:${composerMode}`);if(typeof saved?.text==='string'){$('composer-text').value=saved.text;$('composer-draft-note').textContent='Đã khôi phục bản nháp. Kiểm tra lại link trong nội dung; dùng Tạo lại để lấy thiết lập mới nhất.';}else $('composer-draft-note').textContent='Bạn có thể sửa nội dung; bản nháp được giữ trên tab này.';
 }
 async function copy(text,area){try{await navigator.clipboard.writeText(text);api.toast('Đã sao chép. Bạn tự xem lại và thao tác trên Facebook.');}catch{area?.focus();area?.select();api.toast('Hãy chọn nội dung và dùng Sao chép hoặc Ctrl+C.');}}
 $('field-search').addEventListener('input',render);$('stage-filter').addEventListener('change',render);
 $('pipeline-stages').onclick=e=>{const button=e.target.closest('[data-stage]');if(button){$('stage-filter').value=$('stage-filter').value===button.dataset.stage?'':button.dataset.stage;render();}};
 $('fieldwork-panel').addEventListener('click',e=>{const counts=e.target.closest('[data-counts]'),workflow=e.target.closest('[data-workflow]'),compose=e.target.closest('[data-compose]'),basic=e.target.closest('[data-basic]'),task=e.target.closest('[data-task]');if(counts)openWorkflow(counts.dataset.counts,'counts');if(workflow)openWorkflow(workflow.dataset.workflow);if(compose)openComposer(compose.dataset.compose);if(basic)api.openGroup(getGroup(basic.dataset.basic));if(task){if(task.dataset.type==='verify')api.openGroup(getGroup(task.dataset.task));else openWorkflow(task.dataset.task,task.dataset.type==='review'?'counts':'progress');}});
 watchFormDraft($('workflow-form'),'workflow-draft-note');$('workflow-form').noValidate=true;
 $('workflow-form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget;if(!checkFormValidity(form,activateWorkflowTab))return;const input=Object.fromEntries(new FormData(form)),old=getGroup(input.id);if(!old)return;if(input.surveyUrl&&input.surveyUrl===old.surveyUrl&&input.sourceCode.trim().toUpperCase()!==old.sourceCode){showFormErrors(form,$('workflow-errors'),['sourceCode: Mã nguồn đã đổi nhưng link điền sẵn vẫn giữ nguyên. Hãy tạo lại link đúng mã hoặc xóa link cũ trước khi lưu.'],activateWorkflowTab);return;}const result=api.saveGroup({...old,...input});if(!result.ok){showFormErrors(form,$('workflow-errors'),result.errors,activateWorkflowTab);return;}clearFormDraft(form);$('workflow-dialog').close();api.toast('Đã lưu cập nhật nhóm.');};
 document.querySelectorAll('[data-workflow-tab]').forEach((el,index)=>{el.onclick=()=>activateWorkflowTab(el.dataset.workflowTab);el.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...document.querySelectorAll('[data-workflow-tab]')],next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;activateWorkflowTab(tabs[next].dataset.workflowTab);tabs[next].focus();};});
 $('workflow-stage').addEventListener('change',()=>{updateStageFields(true);captureFormDraft($('workflow-form'));});
 $('discard-workflow-draft').onclick=()=>{const form=$('workflow-form'),id=form.elements.id.value;clearFormDraft(form,{discardAll:true});$('workflow-dialog').close();openWorkflow(id,workflowTab);api.toast('Đã bỏ bản nháp, dữ liệu đã lưu vẫn giữ nguyên.');};
 document.querySelectorAll('[data-remind]').forEach(el=>el.onclick=()=>{const form=$('workflow-form'),day=new Date(`${today()}T12:00:00+07:00`);day.setUTCDate(day.getUTCDate()+Number(el.dataset.remind));form.elements.nextActionAt.value=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(day);if(!form.elements.nextAction.value)form.elements.nextAction.value='Kiểm tra tiến độ và phản hồi';captureFormDraft(form);});
 for(const name of ['received','responses','rejected'])$('workflow-form').elements.namedItem(name).addEventListener('input',qualityPreview);
 $('mark-reviewed').onclick=()=>{const f=$('workflow-form');f.elements.lastReviewedAt.value=today();f.elements.nextActionAt.value='';f.elements.nextAction.value='';captureFormDraft(f);api.toast('Đã điền ngày hôm nay. Bấm Lưu cập nhật để ghi nhận.');};
 $('pause-recruitment').onclick=()=>{const f=$('workflow-form');f.elements.stage.value='paused';f.elements.nextActionAt.value='';f.elements.nextAction.value='';if(!f.elements.stopReason.value)f.elements.stopReason.value='Tạm dừng tuyển tại nhóm này; giữ lại dữ liệu và số mẫu.';captureFormDraft(f);api.toast('Đã chọn tạm dừng. Bấm Lưu cập nhật để ghi nhận.');};
 $('workflow-source-help').onclick=sourceHelp;$('source-help').onclick=sourceHelp;
 $('compose-admin').onclick=()=>{composerMode='admin';fillComposer();};$('compose-invite').onclick=()=>{composerMode='invite';fillComposer();};$('copy-composer').onclick=()=>copy($('composer-text').value,$('composer-text'));$('composer-source').onclick=()=>copy(composerGroup.sourceCode||makeSourceCode(composerGroup.id),$('composer-source-code'));
 $('composer-text').addEventListener('input',()=>{if(!composerGroup)return;writeDraft(`composer:${composerGroup.id}:${composerMode}`,{text:$('composer-text').value.slice(0,15000)});$('composer-draft-note').textContent='Bản nháp đã được giữ trên tab này.';});
 $('regenerate-composer').onclick=()=>{const regenerate=()=>{clearDraft(`composer:${composerGroup.id}:${composerMode}`);fillComposer();};if(readDraft(`composer:${composerGroup.id}:${composerMode}`))api.confirmAction('Tạo lại nội dung?', 'Bản đang sửa sẽ được thay bằng mẫu từ thiết lập mới nhất của khảo sát. Bạn có thể sao chép để giữ lại trước khi tạo lại.',regenerate);else regenerate();};
 $('composer-setup').onclick=()=>{$('composer-dialog').close();api.changeView('plan');$('campaign-form').elements.formUrl.focus();};$('start-setup').onclick=()=>{api.changeView('plan');$('campaign-form').elements.formUrl.focus();};$('start-add').onclick=()=>api.openGroup();$('start-counts').onclick=()=>{if(groups().length)openWorkflow(groups()[0].id,'counts');};
 $('edit-sampling').onclick=()=>{const {sampling,campaign,groups:rows}=api.getState(),value=normalizeSampling(sampling),form=$('sampling-form');for(const key of ['hcmTarget','hnTarget','hcmActual','hnActual','deadline'])form.elements.namedItem(key).value=value[key];for(const {id}of AGE_BANDS)form.elements.namedItem(`age-${id}`).value=value.ages[id];$('sampling-errors').textContent='';$('sampling-total').textContent=`Hiện có ${responseSummary(rows,campaign.baseline).valid} mẫu hợp lệ. Tổng thành phố và tổng độ tuổi đều không được vượt số này.`;$('sampling-dialog').showModal();};
 $('sampling-form').onsubmit=e=>{e.preventDefault();const input=Object.fromEntries(new FormData(e.currentTarget));input.ages=Object.fromEntries(AGE_BANDS.map(({id})=>[id,input[`age-${id}`]]));const {groups:rows,campaign}=api.getState(),result=validateSampling(input,responseSummary(rows,campaign.baseline).valid);if(!result.ok){$('sampling-errors').textContent=result.errors.join('\n');return;}if(api.setSampling(result.value)!==false){$('sampling-dialog').close();api.toast('Đã cập nhật phân bổ, tổng phản hồi giữ nguyên.');}};
 $('field-add').onclick=()=>api.openGroup();$('go-discover').onclick=()=>api.changeView('discover');$('field-backup').onclick=()=>api.exportJson();
 $('fieldwork-guide').onclick=()=>api.showInfo('Một buổi thu thập khảo sát',`<h3>Trước khi đăng</h3><p>Kiểm tra nội quy, xin phép quản trị nếu cần và ghi trạng thái. “Được phép đăng” là kết quả xin phép; “Bài chờ duyệt” và “Đã đăng bài” là hai giai đoạn khác nhau. Quyền đăng ẩn danh không thay thế quyền đăng khảo sát.</p><h3>Khi có nhiều nhóm đang chờ</h3><p>Ghi việc tiếp theo và ngày hẹn. Bàn thu thập nhắc khi mở app; app không gửi tin, đăng lại hay thông báo khi đóng. Nhóm tạm dừng hoặc bị từ chối không có nhắc tiếp cận lại.</p><h3>Sau khi có phản hồi</h3><p>Nhập tổng lũy kế từ từng nguồn, tách mẫu đã rà soát hợp lệ và mẫu loại. Phần còn lại là chưa rà soát. Chỉ hợp lệ được cộng vào mục tiêu 500. Mẫu từ nguồn khác chỉ nhập vào thiết lập nếu chưa nằm trong các nhóm.</p><h3>Trước khi kết thúc buổi</h3><p>Cập nhật phân bổ thành phố, độ tuổi từ dữ liệu sàng lọc thật. Nếu muốn ngừng một nhóm, chọn “Dừng tuyển, giữ mẫu”. Xuất JSON để mang sang thiết bị khác hoặc dự phòng.</p>`);
 return {render,openWorkflow,openComposer};
}
